// deeplink_integration_test.dart - 딥링크 통합 테스트
// 앱 간 라우팅 & 파라미터 전달 검증

import 'package:flutter_test/flutter_test.dart';
import 'package:fl_deeplink/deeplink_manager.dart';

void main() {
  group('DeepLink Integration Tests', () {
    late DeepLinkManager manager;

    setUp(() {
      manager = DeepLinkManager();
    });

    tearDown(() async {
      await manager.dispose();
    });

    // ==================== 딥링크 URI 파싱 테스트 ====================
    group('DeepLink URI Parsing', () {
      test('Runner 딥링크 파싱: freelang://run?code=BASE64', () {
        const code = 'print "Hello"';
        final link = manager.createRunnerLink(code);

        expect(link, contains('freelang://run?code='));
        expect(link, contains('UHJpbnQ'));  // "Print" base64
      });

      test('IDE 딥링크 파싱: freelang://edit?snippet_id=X', () {
        const snippetId = 'snippet_123';
        final link = manager.createIDELink(snippetId);

        expect(link, equals('freelang://edit?snippet_id=snippet_123'));
      });

      test('Game 딥링크 파싱: freelang://game?dsl=BASE64', () {
        const dsl = 'scene TestGame { sprite Test { x=100 } }';
        final link = manager.createGameLink(dsl);

        expect(link, contains('freelang://game?dsl='));
      });

      test('Hub 딥링크 파싱: freelang://share?snippet_id=X', () {
        const snippetId = 'snippet_456';
        final link = manager.createHubLink(snippetId);

        expect(link, equals('freelang://share?snippet_id=snippet_456'));
      });
    });

    // ==================== Base64 인코딩/디코딩 ====================
    group('Base64 Encoding/Decoding', () {
      test('코드 Base64 인코딩', () {
        const code = 'let x = 10\nprint x';
        final encoded = manager.encodeBase64(code);

        expect(encoded, isA<String>());
        expect(encoded.length, greaterThan(0));
      });

      test('Base64 디코딩 왕복', () {
        const original = 'let fib(n) { if n <= 1 { n } else { fib(n-1) + fib(n-2) } }';
        final encoded = manager.encodeBase64(original);
        final decoded = manager.decodeBase64(encoded);

        expect(decoded, equals(original));
      });

      test('특수문자 인코딩', () {
        const code = 'print "한글 테스트 🚀"';
        final encoded = manager.encodeBase64(code);
        final decoded = manager.decodeBase64(encoded);

        expect(decoded, equals(code));
      });

      test('빈 코드 인코딩', () {
        const code = '';
        final encoded = manager.encodeBase64(code);
        final decoded = manager.decodeBase64(encoded);

        expect(decoded, equals(''));
      });
    });

    // ==================== 딥링크 생성 체인 ====================
    group('DeepLink Chain Creation', () {
      test('Hub → IDE 체인: snippet_id 전달', () {
        const snippetId = 'fibonacci_123';
        final ideLink = manager.createIDELink(snippetId);

        expect(ideLink, contains(snippetId));
        expect(ideLink, startsWith('freelang://edit'));
      });

      test('IDE → Runner 체인: 코드 Base64 전달', () {
        const code = 'print "Hello from IDE"';
        final runnerLink = manager.createRunnerLink(code);

        expect(runnerLink, contains('freelang://run'));
        expect(runnerLink, contains('code='));

        // 링크에서 코드 추출
        final uri = Uri.parse(runnerLink);
        final encodedCode = uri.queryParameters['code'];
        final decodedCode = manager.decodeBase64(encodedCode!);

        expect(decodedCode, equals(code));
      });

      test('IDE → Game 체인: DSL 전달', () {
        const dsl = '''
          scene Game {
            sprite Player { x=160, y=300 }
            on touch(x, y) { move_to(x, y) }
          }
        ''';
        final gameLink = manager.createGameLink(dsl);

        expect(gameLink, contains('freelang://game'));

        final uri = Uri.parse(gameLink);
        final encodedDsl = uri.queryParameters['dsl'];
        final decodedDsl = manager.decodeBase64(encodedDsl!);

        expect(decodedDsl.contains('scene Game'), isTrue);
      });

      test('Game → Hub 체인: 게임 결과 공유', () {
        const gameId = 'game_runner_789';
        final hubLink = manager.createHubLink(gameId);

        expect(hubLink, contains(gameId));
        expect(hubLink, startsWith('freelang://share'));
      });
    });

    // ==================== URI 파라미터 검증 ====================
    group('URI Parameter Validation', () {
      test('Runner 파라미터: code 필수', () {
        const code = 'print 42';
        final link = manager.createRunnerLink(code);
        final uri = Uri.parse(link);

        expect(uri.queryParameters.containsKey('code'), isTrue);
      });

      test('IDE 파라미터: snippet_id 필수', () {
        const snippetId = 'test_123';
        final link = manager.createIDELink(snippetId);
        final uri = Uri.parse(link);

        expect(uri.queryParameters.containsKey('snippet_id'), isTrue);
        expect(uri.queryParameters['snippet_id'], equals(snippetId));
      });

      test('Game 파라미터: dsl 필수', () {
        const dsl = 'scene Test {}';
        final link = manager.createGameLink(dsl);
        final uri = Uri.parse(link);

        expect(uri.queryParameters.containsKey('dsl'), isTrue);
      });

      test('Hub 파라미터: snippet_id 필수', () {
        const snippetId = 'share_123';
        final link = manager.createHubLink(snippetId);
        final uri = Uri.parse(link);

        expect(uri.queryParameters.containsKey('snippet_id'), isTrue);
      });
    });

    // ==================== 딥링크 스트림 구독 테스트 ====================
    group('DeepLinkManager Stream Subscription', () {
      test('스트림 초기화 성공', () async {
        expect(manager.onDeepLink, isNotNull);
      });

      test('DeepLink 객체 생성 확인', () async {
        final runnerLink = manager.createRunnerLink('print 1');
        final uri = Uri.parse(runnerLink);

        expect(uri.scheme, equals('freelang'));
        expect(uri.host, equals('run'));
      });

      test('여러 딥링크 순차 생성', () async {
        final links = [
          manager.createRunnerLink('print 1'),
          manager.createIDELink('snippet_1'),
          manager.createGameLink('scene {}'),
          manager.createHubLink('snippet_2'),
        ];

        expect(links.length, equals(4));
        expect(links[0], contains('freelang://run'));
        expect(links[1], contains('freelang://edit'));
        expect(links[2], contains('freelang://game'));
        expect(links[3], contains('freelang://share'));
      });
    });

    // ==================== 에러 처리 테스트 ====================
    group('Error Handling', () {
      test('빈 코드 처리', () {
        final link = manager.createRunnerLink('');
        expect(link, contains('freelang://run?code='));
      });

      test('특수문자 처리', () {
        const code = 'print "a=b&c=d?x=y"';
        final link = manager.createRunnerLink(code);
        final uri = Uri.parse(link);

        expect(uri.queryParameters.containsKey('code'), isTrue);
      });

      test('매우 긴 코드 Base64 처리', () {
        final longCode = 'let x = 1\n' * 1000;
        final encoded = manager.encodeBase64(longCode);
        final decoded = manager.decodeBase64(encoded);

        expect(decoded, equals(longCode));
      });

      test('잘못된 Base64 디코딩 처리', () {
        expect(
          () => manager.decodeBase64('!@#$%^'),
          throwsException,
        );
      });
    });

    // ==================== 앱 간 라우팅 시나리오 ====================
    group('App-to-App Routing Scenarios', () {
      test('시나리오 1: Hub에서 스니펫 발견 → IDE에서 편집', () async {
        // Hub에서 스니펫 발견
        const snippetId = 'tutorial_fibonacci';
        final ideLink = manager.createIDELink(snippetId);

        // IDE로 라우팅
        expect(ideLink, contains('freelang://edit'));
        expect(ideLink, contains(snippetId));
      });

      test('시나리오 2: IDE에서 코드 완성 → Runner에서 실행', () async {
        // IDE에서 코드 작성
        const code = 'let add(a, b) { a + b }\nprint add(5, 3)';
        final runnerLink = manager.createRunnerLink(code);

        // Runner로 라우팅
        expect(runnerLink, contains('freelang://run'));

        // Runner에서 코드 추출 및 검증
        final uri = Uri.parse(runnerLink);
        final decoded = manager.decodeBase64(uri.queryParameters['code']!);
        expect(decoded, contains('add'));
        expect(decoded, contains('print'));
      });

      test('시나리오 3: IDE에서 게임 DSL 작성 → Game에서 실행', () async {
        // IDE에서 게임 DSL 작성
        const dsl = '''
          scene MainGame {
            sprite Player { x = 100, y = 200 }
            on touch(x, y) { Player.move_to(x, y) }
          }
        ''';
        final gameLink = manager.createGameLink(dsl);

        // Game으로 라우팅
        expect(gameLink, contains('freelang://game'));

        final uri = Uri.parse(gameLink);
        final decodedDsl = manager.decodeBase64(uri.queryParameters['dsl']!);
        expect(decodedDsl, contains('MainGame'));
        expect(decodedDsl, contains('Player'));
      });

      test('시나리오 4: Game 플레이 결과 → Hub에서 공유', () async {
        // Game 플레이 완료
        const gameResultId = 'game_result_2026_03_25_001';
        final hubLink = manager.createHubLink(gameResultId);

        // Hub로 라우팅
        expect(hubLink, contains('freelang://share'));
        expect(hubLink, contains(gameResultId));
      });

      test('시나리오 5: 완전 루프 (Hub → IDE → Runner → Game → Hub)', () async {
        // 1. Hub에서 스니펫 발견
        const initialSnippetId = 'learning_game_dsl';
        final ideLink1 = manager.createIDELink(initialSnippetId);
        expect(ideLink1, contains(initialSnippetId));

        // 2. IDE에서 게임 DSL로 수정
        const gameDsl = 'scene { sprite {} }';
        final gameLink = manager.createGameLink(gameDsl);
        expect(gameLink, contains('freelang://game'));

        // 3. 게임 실행 결과
        const gamePlayId = 'gameplay_001';
        final finalHubLink = manager.createHubLink(gamePlayId);
        expect(finalHubLink, contains(gamePlayId));

        // 모든 링크 검증
        expect(ideLink1, isNotEmpty);
        expect(gameLink, isNotEmpty);
        expect(finalHubLink, isNotEmpty);
      });
    });

    // ==================== 딥링크 포맷 일관성 ====================
    group('DeepLink Format Consistency', () {
      test('모든 스킴이 freelang://로 시작', () {
        final links = [
          manager.createRunnerLink('test'),
          manager.createIDELink('test'),
          manager.createGameLink('test'),
          manager.createHubLink('test'),
        ];

        for (final link in links) {
          expect(link, startsWith('freelang://'));
        }
      });

      test('각 앱 호스트 정확성', () {
        expect(manager.createRunnerLink('code'), contains('freelang://run?'));
        expect(manager.createIDELink('id'), contains('freelang://edit?'));
        expect(manager.createGameLink('dsl'), contains('freelang://game?'));
        expect(manager.createHubLink('id'), contains('freelang://share?'));
      });

      test('파라미터 순서 일관성', () {
        final link1 = manager.createRunnerLink('code1');
        final link2 = manager.createRunnerLink('code2');

        // 둘 다 같은 구조
        expect(link1.split('?')[0], equals(link2.split('?')[0]));
      });
    });
  });
}

