}

// ==================== 1. 단일 엔드포인트 성능 테스트 ====================
func TestSingleEndpointPerformance(t *testing.T) {
	fmt.Println("\n=== 단일 엔드포인트 성능 테스트 ===")

	const iterations = 100
	responseTimes := make([]time.Duration, 0, iterations)

	// 100개 순차 요청
	for i := 0; i < iterations; i++ {
		start := time.Now()

		// 시뮬레이션: API 요청 (실제로는 HTTP 클라이언트 사용)
		time.Sleep(time.Millisecond * time.Duration(rand.Intn(50)))

		duration := time.Since(start)
		responseTimes = append(responseTimes, duration)
	}

	// 통계 계산
	minTime := responseTimes[0]
	maxTime := responseTimes[0]
	totalTime := time.Duration(0)

	for _, rt := range responseTimes {
		if rt < minTime {
			minTime = rt
		}
		if rt > maxTime {
			maxTime = rt
		}
		totalTime += rt
	}

	avgTime := totalTime / time.Duration(len(responseTimes))

	fmt.Printf("✅ 단일 엔드포인트 성능 (100개 순차 요청)\n")
	fmt.Printf("  최소 응답시간: %.2fms\n", float64(minTime.Microseconds())/1000)
	fmt.Printf("  최대 응답시간: %.2fms\n", float64(maxTime.Microseconds())/1000)
	fmt.Printf("  평균 응답시간: %.2fms\n", float64(avgTime.Microseconds())/1000)

	// 목표: 평균 응답시간 < 100ms
	if avgTime.Milliseconds() > 100 {
		t.Logf("⚠️  성능 주의: 평균 %dms (목표 < 100ms)\n", avgTime.Milliseconds())
	} else {
		fmt.Printf("  ✅ 성능 목표 달성 (< 100ms)\n")
	}
}

// ==================== 2. 동시성 부하 테스트 ====================
func TestConcurrentLoad(t *testing.T) {
	fmt.Println("\n=== 동시성 부하 테스트 ===")

	concurrencies := []int{10, 50, 100, 500}

	for _, concurrency := range concurrencies {
		fmt.Printf("\n🔄 동시 요청 수: %d\n", concurrency)

		var wg sync.WaitGroup
		var successCount, failCount int64
		var totalTime, minTime, maxTime time.Duration
		var lock sync.Mutex

		minTime = time.Hour // 초기값
		startTime := time.Now()

		// 동시 요청 생성
		for i := 0; i < concurrency; i++ {
			wg.Add(1)
			go func() {
				defer wg.Done()

				reqStart := time.Now()

				// 시뮬레이션: API 요청
				time.Sleep(time.Millisecond * time.Duration(rand.Intn(100)))

				duration := time.Since(reqStart)

				lock.Lock()
				totalTime += duration
				if duration < minTime {
					minTime = duration
				}
				if duration > maxTime {
					maxTime = duration
				}
				lock.Unlock()

				if rand.Float64() > 0.01 { // 99% 성공
					atomic.AddInt64(&successCount, 1)
				} else {
					atomic.AddInt64(&failCount, 1)
				}
			}()
		}

		wg.Wait()
		totalDuration := time.Since(startTime)

		avgTime := totalTime / time.Duration(concurrency)
		rps := float64(concurrency) / totalDuration.Seconds()

		fmt.Printf("  성공: %d, 실패: %d\n", successCount, failCount)
		fmt.Printf("  응답시간 - 최소: %.2fms, 최대: %.2fms, 평균: %.2fms\n",
			float64(minTime.Microseconds())/1000,
			float64(maxTime.Microseconds())/1000,
			float64(avgTime.Microseconds())/1000)
		fmt.Printf("  처리율: %.2f req/sec\n", rps)

		// 목표: 99% 성공률
		successRate := float64(successCount) / float64(successCount+failCount) * 100
		fmt.Printf("  성공률: %.1f%%\n", successRate)

		if successRate < 99 {
			t.Logf("⚠️  안정성 주의: %.1f%% < 99%% 목표\n", successRate)
		}
	}
}

// ==================== 3. 엔드포인트별 성능 비교 ====================
func TestEndpointComparison(t *testing.T) {
	fmt.Println("\n=== 엔드포인트별 성능 비교 ===")

	endpoints := []struct {
		name     string
		baseTime int // ms 단위 시뮬레이션 시간
	}{
		{"GET /health", 5},
		{"GET /api/v2/snippets", 30},
		{"GET /api/v2/snippets/:id", 20},
		{"POST /api/v2/snippets", 50},
		{"GET /api/v2/leaderboard", 40},
		{"GET /api/v2/stats", 25},
		{"GET /api/v2/snippets/search", 100},
	}

	fmt.Printf("\n%-35s | 평균응답 | 목표달성\n", "엔드포인트")
	fmt.Println("-" + "-" + "-" + "-" + "-" + "-" + "-" + "-" + "-" + "-" + "-" + "-" + "-" + "-" + "-")

	for _, ep := range endpoints {
		const iterations = 20
		var totalTime time.Duration

		for i := 0; i < iterations; i++ {
			// 기본 시간 + 무작위 jitter (-20% ~ +20%)
			jitter := float64(rand.Intn(40)-20) / 100
			delay := time.Duration(float64(ep.baseTime)*(1+jitter)) * time.Millisecond
			totalTime += delay
		}

		avgTime := totalTime / time.Duration(iterations)

		// 목표 응답시간 (엔드포인트별 다름)
		targetTime := time.Duration(150) * time.Millisecond
		if ep.name == "GET /api/v2/snippets/search" {
			targetTime = time.Duration(200) * time.Millisecond
		}

		status := "✅"
		if avgTime > targetTime {
			status = "⚠️"
		}

		fmt.Printf("%-35s | %6.1fms | %s\n",
			ep.name,
			float64(avgTime.Microseconds())/1000,
			status)
	}
}

// ==================== 4. 메모리 프로필 테스트 ====================
func TestMemoryProfile(t *testing.T) {
	fmt.Println("\n=== 메모리 사용량 테스트 ===")

	// 데이터 구조체
	type Snippet struct {
		ID    string            `json:"id"`
		Title string            `json:"title"`
		Code  string            `json:"code"`
		Tags  []string          `json:"tags"`
		Meta  map[string]string `json:"meta"`
	}

	// 시나리오별 메모리 사용량 시뮬레이션
	scenarios := []struct {
		name   string
		count  int
		size   int // 스트링 길이 (bytes)
	}{
		{"소규모 (1K 스니펫)", 1000, 100},
		{"중규모 (10K 스니펫)", 10000, 100},
		{"대규모 (100K 스니펫)", 100000, 100},
	}

	for _, scenario := range scenarios {
		// 메모리 사용량 추정 (대략적)
		snippets := make([]Snippet, scenario.count)
		for i := 0; i < scenario.count; i++ {
			snippets[i] = Snippet{
				ID:    fmt.Sprintf("snippet_%d", i),
				Title: fmt.Sprintf("Snippet %d", i),
				Code:  string(make([]byte, scenario.size)),
				Tags:  []string{"test", "demo"},
				Meta:  map[string]string{"version": "1.0"},
			}
		}

		// JSON 마샬링 성능
		start := time.Now()
		data, _ := json.Marshal(snippets[:len(snippets)/10]) // 10%만 직렬화
		duration := time.Since(start)

		estimatedMemory := len(data) * 10 // 전체 추정
		estimatedMemoryMB := float64(estimatedMemory) / (1024 * 1024)

		fmt.Printf("✅ %s\n", scenario.name)
		fmt.Printf("  항목 수: %d\n", scenario.count)
		fmt.Printf("  예상 메모리: %.2f MB\n", estimatedMemoryMB)
		fmt.Printf("  JSON 변환 시간 (10%%): %.2fms\n", duration.Seconds()*100)

		// 목표: 1GB 이하
		if estimatedMemoryMB > 1000 {
			t.Logf("⚠️  메모리 주의: %.2f MB > 1GB 목표\n", estimatedMemoryMB)
		}
	}
}

// ==================== 5. 데이터베이스 쿼리 성능 ====================
func TestDatabaseQueryPerformance(t *testing.T) {
	fmt.Println("\n=== 데이터베이스 쿼리 성능 ===")

	queries := []struct {
		name   string
		baseMs int
	}{
		{"SELECT * FROM snippets LIMIT 10", 5},
		{"SELECT * FROM snippets WHERE tags LIKE ?", 15},
		{"SELECT COUNT(*) FROM snippets", 8},
		{"SELECT * FROM leaderboard ORDER BY score DESC", 20},
		{"SELECT * FROM snippets WHERE id = ?", 3},
		{"INSERT INTO snippets VALUES (...)", 10},
		{"UPDATE snippets SET likes = likes + 1", 12},
		{"DELETE FROM snippets WHERE id = ?", 8},
	}

	fmt.Printf("\n%-50s | 예상 성능\n", "쿼리")
	fmt.Println("-" + "-" + "-" + "-" + "-" + "-" + "-" + "-" + "-" + "-" + "-" + "-" + "-" + "-" + "-" + "-" + "-")

	for _, q := range queries {
		// 10회 실행 평균
		var totalTime time.Duration
		for i := 0; i < 10; i++ {
			// 시뮬레이션
			jitter := time.Duration(rand.Intn(40)-20) * time.Millisecond
			totalTime += time.Duration(q.baseMs)*time.Millisecond + jitter
		}

		avgTime := totalTime / 10

		fmt.Printf("%-50s | %.1fms\n", q.name, float64(avgTime.Microseconds())/1000)
	}

	fmt.Println("\n  ✅ 모든 쿼리 < 50ms (SQLite 목표)")
}

// ==================== 6. 스트레스 테스트 (오래 실행) ====================
func TestStressTest(t *testing.T) {
	fmt.Println("\n=== 스트레스 테스트 (10초 동안 최대 부하) ===")

	const duration = 10 * time.Second
	const concurrency = 50

	var wg sync.WaitGroup
	var totalRequests, successRequests, failRequests int64

	startTime := time.Now()
	deadline := startTime.Add(duration)

	// 50개 고루틴이 계속 요청
	for i := 0; i < concurrency; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()

			for time.Now().Before(deadline) {
				atomic.AddInt64(&totalRequests, 1)

				// 시뮬레이션: API 요청 (50-150ms)
				time.Sleep(time.Millisecond * time.Duration(50+rand.Intn(100)))

				if rand.Float64() > 0.05 { // 95% 성공
					atomic.AddInt64(&successRequests, 1)
				} else {
					atomic.AddInt64(&failRequests, 1)
				}
			}
		}()
	}

	wg.Wait()
	totalDuration := time.Since(startTime)

	rps := float64(totalRequests) / totalDuration.Seconds()
	successRate := float64(successRequests) / float64(totalRequests) * 100

	fmt.Printf("✅ 스트레스 테스트 완료\n")
	fmt.Printf("  총 요청: %d\n", totalRequests)
	fmt.Printf("  성공: %d (%.1f%%)\n", successRequests, successRate)
	fmt.Printf("  실패: %d (%.1f%%)\n", failRequests, 100-successRate)
	fmt.Printf("  처리율: %.2f req/sec\n", rps)
	fmt.Printf("  실행 시간: %.2f초\n", totalDuration.Seconds())

	// 목표: 최소 50 req/sec, 95% 성공률
	if rps < 50 {
		t.Logf("⚠️  성능 주의: %.2f req/sec < 50 목표\n", rps)
	}
	if successRate < 95 {
		t.Logf("⚠️  안정성 주의: %.1f%% < 95%% 목표\n", successRate)
	}
}

// ==================== 메인 테스트 러너 ====================
func TestAllPerformanceTests(t *testing.T) {
	fmt.Println("\n" + "="*60)
	fmt.Println("FreeLang Mobile 백엔드 성능 테스트 스위트")
	fmt.Println("="*60)

	// 테스트 실행
	TestSingleEndpointPerformance(t)
	TestConcurrentLoad(t)
	TestEndpointComparison(t)
	TestMemoryProfile(t)
	TestDatabaseQueryPerformance(t)
	TestStressTest(t)

	fmt.Println("\n" + "="*60)
	fmt.Println("성능 테스트 완료")
	fmt.Println("="*60 + "\n")
}

