// e2e_scenario_test.dart - 전체 사용자 흐름 E2E 테스트
// Hub → IDE → Runner → Game → Hub 자체 성장 루프 검증

import 'package:flutter_test/flutter_test.dart';
import 'package:runner/engine_bridge.dart';

void main() {
  group('E2E User Flow Scenarios', () {
    late ScenarioContext context;

    setUp(() {
      context = ScenarioContext();
    });

    tearDown(() async {
      await context.cleanup();
    });

    // ==================== 시나리오 1: 초보자 학습 흐름 ====================
    group('시나리오 1: 초보자 학습 흐름', () {
      test('Hub에서 "Hello World" 튜토리얼 발견 → Runner에서 실행', () async {
        // 1️⃣ Hub: 튜토리얼 발견
        final tutorial = context.findTutorial('hello-world');
        expect(tutorial, isNotNull);
        expect(tutorial.title, contains('Hello'));

        // 2️⃣ IDE 열기 (딥링크: freelang://edit?snippet_id=hello-world)
        final ideSnippet = context.openIDEWithSnippet(tutorial.snippetId);
        expect(ideSnippet.code, contains('print'));

        // 3️⃣ Runner 실행 (코드 그대로)
        final result = await FlEngineBridge.run(ideSnippet.code);
        expect(result.success, true);
        expect(result.output, contains('Hello'));

        // 4️⃣ 결과 저장
        context.recordLearning(
          tutorialId: tutorial.id,
          completed: true,
          timeMs: 120,
        );

        expect(context.completedTutorials, contains('hello-world'));
      });

      test('프로그래밍 기초 5단계 완료', () async {
        final tutorials = [
          'hello-world',
          'variables-and-types',
          'functions-basics',
          'loops-and-conditions',
          'arrays-and-data',
        ];

        for (final tutorialId in tutorials) {
          // 각 튜토리얼 실행
          final tutorial = context.findTutorial(tutorialId);
          final result = await FlEngineBridge.run(tutorial.code);

          expect(result.success, true, reason: '$tutorialId 실행 실패');
          context.recordLearning(tutorialId: tutorial.id, completed: true);
        }

        // 모든 튜토리얼 완료 확인
        expect(context.completedTutorials.length, equals(tutorials.length));
      });
    });

    // ==================== 시나리오 2: 코드 개발 & 반복 ====================
    group('시나리오 2: 코드 개발 & 반복 사이클', () {
      test('피보나치 함수 구현 및 최적화', () async {
        // 1️⃣ 초안 작성
        const draft1 = '''
          let fib(n) {
            if n <= 1 { n }
            else { fib(n-1) + fib(n-2) }
          }
          print fib(10)
        ''';

        var result = await FlEngineBridge.run(draft1);
        expect(result.success, true);
        expect(result.output, contains('55')); // fib(10) = 55

        // IDE에서 저장
        context.saveSnippet('fibonacci-v1', draft1);

        // 2️⃣ 메모이제이션으로 개선
        const draft2 = '''
          let memo = {}
          let fib(n) {
            if memo[n] { memo[n] }
            else {
              let result = if n <= 1 { n } else { fib(n-1) + fib(n-2) }
              memo[n] = result
              result
            }
          }
          print fib(20)
        ''';

        result = await FlEngineBridge.run(draft2);
        expect(result.success, true);
        expect(result.output, contains('6765')); // fib(20) = 6765

        context.saveSnippet('fibonacci-v2', draft2);

        // 3️⃣ 성능 비교
        final time1 = context.measureExecutionTime(draft1);
        final time2 = context.measureExecutionTime(draft2);

        expect(time2, lessThan(time1 * 10), // 메모이제이션이 훨씬 빨라야 함
            reason: '최적화 안 됨: v2가 v1보다 빨라야 함');

        // Hub에 공유
        context.shareSnippet(
          'fibonacci-v2',
          tags: ['algorithm', 'recursion', 'optimization'],
        );
      });

      test('버그 수정 & 디버깅 흐름', () async {
        // 1️⃣ 버그 있는 코드
        const buggyCode = '''
          let sum(arr) {
            let total = 0
            let i = 0
            while i < arr.length {
              total = total + arr[i]
              // i++; 증가를 빠뜨렸다!
            }
            total
          }
          print sum([1, 2, 3, 4, 5])
        ''';

        // IDE에서 검증
        final errors = await FlEngineBridge.check(buggyCode);
        expect(errors, isNotEmpty, reason: '무한 루프 감지 안 됨');

        // 2️⃣ 수정된 코드
        const fixedCode = '''
          let sum(arr) {
            let total = 0
            let i = 0
            while i < arr.length {
              total = total + arr[i]
              i = i + 1
            }
            total
          }
          print sum([1, 2, 3, 4, 5])
        ''';

        final result = await FlEngineBridge.run(fixedCode);
        expect(result.success, true);
        expect(result.output, contains('15')); // 1+2+3+4+5=15

        context.recordBugFix(originalCode: buggyCode, fixedCode: fixedCode);
      });
    });

    // ==================== 시나리오 3: 게임 DSL 만들기 ====================
    group('시나리오 3: 게임 개발 흐름', () {
      test('간단한 게임 DSL 작성 & 실행', () async {
        // 1️⃣ IDE에서 게임 DSL 작성
        const gameDsl = '''
          scene MainGame {
            sprite Player { x=160, y=300, w=32, h=32 }
            sprite Enemy { x=50, y=100, w=24, h=24 }

            on touch(tx, ty) {
              if tx > 100 && tx < 220 && ty > 280 && ty < 320 {
                Player.move_to(tx, ty)
              }
            }

            on update(dt) {
              if Player.x > 300 {
                scene_change("Win")
              }
            }
          }

          scene Win {
            text "You Win!" at (160, 240)
            on tap { scene_change("MainGame") }
          }
        ''';

        // 2️⃣ 게임 DSL 검증
        final errors = await FlEngineBridge.check(gameDsl);
        expect(errors.isEmpty, true, reason: 'DSL 파싱 에러');

        // 3️⃣ 게임 실행 (시뮬레이션)
        final gameContext = context.runGame(gameDsl);
        expect(gameContext, isNotNull);

        // 4️⃣ 게임 인터랙션 시뮬레이션
        gameContext.simulateTouchAt(160, 320);
        expect(gameContext.currentScene, equals('MainGame'));

        gameContext.simulateTouchAt(350, 320); // 승리 조건
        await Future.delayed(Duration(milliseconds: 100));
        expect(gameContext.currentScene, equals('Win'));

        // Hub에 게임 공유
        context.shareSnippet(
          gameDsl,
          tags: ['game', 'dsl', 'interactive'],
        );
      });
    });

    // ==================== 시나리오 4: 커뮤니티 협업 ====================
    group('시나리오 4: 커뮤니티 협업 흐름', () {
      test('스니펫 공유 → 좋아요 → 포크 → 수정 → 공유', () async {
        // 1️⃣ Alice가 스니펫 공유
        const originalCode = 'let add(a, b) { a + b }\nprint add(3, 4)';

        context.createUser('alice');
        context.shareSnippet(
          originalCode,
          author: 'alice',
          title: 'Simple Add Function',
          tags: ['function', 'basic'],
        );
        final snippetId = context.lastSnippetId;

        // 2️⃣ Bob이 스니펫 발견 & 좋아요
        context.createUser('bob');
        context.likeSnippet(snippetId);

        // 3️⃣ Bob이 포크 (수정)
        const bobVersion = '''
          let add(a, b) { a + b }
          let subtract(a, b) { a - b }
          print add(10, 5)
          print subtract(10, 5)
        ''';

        context.createUser('bob');
        final bobSnippetId = context.forkSnippet(
          originalSnippetId: snippetId,
          newCode: bobVersion,
          author: 'bob',
        );

        // 4️⃣ Bob의 버전 실행 확인
        var result = await FlEngineBridge.run(bobVersion);
        expect(result.success, true);
        expect(result.output, contains('15')); // add(10,5)
        expect(result.output, contains('5')); // subtract(10,5)

        // 5️⃣ Carol도 참여
        context.createUser('carol');
        context.likeSnippet(bobSnippetId);

        // 커뮤니티 통계
        expect(context.getSnippetLikes(snippetId), greaterThan(0));
        expect(context.getCommunitySize(), equals(3));
      });

      test('튜토리얼 작성 & 학생 리뷰', () async {
        context.createUser('teacher');
        context.createUser('student1');
        context.createUser('student2');

        // 튜토리얼 작성
        const tutorialCode = '''
          // 소수 판별 함수
          let is_prime(n) {
            if n < 2 { false }
            else {
              let i = 2
              let found = false
              while i * i <= n {
                if n % i == 0 { found = true }
                i = i + 1
              }
              !found
            }
          }
          print is_prime(17)
          print is_prime(20)
        ''';

        context.createTutorial(
          title: 'Prime Number Checker',
          code: tutorialCode,
          steps: [
            'is_prime 함수 구현',
            '루프로 2부터 n까지 확인',
            '약수 찾으면 false 반환',
          ],
          author: 'teacher',
        );

        // 학생들 완료
        final result = await FlEngineBridge.run(tutorialCode);
        expect(result.success, true);
        expect(result.output, contains('true')); // is_prime(17)
        expect(result.output, contains('false')); // is_prime(20)

        context.recordTutorialCompletion('student1', progress: 100);
        context.recordTutorialCompletion('student2', progress: 100);

        expect(context.getTutorialCompletionRate(), equals(1.0));
      });
    });

    // ==================== 시나리오 5: 자체 성장 루프 검증 ====================
    group('시나리오 5: 자체 성장 루프 (Full Cycle)', () {
      test('Hub → IDE → Runner → Game → Hub 완전 사이클', () async {
        // 1️⃣ HUB: 튜토리얼 발견
        final tutorial = context.findTutorial('game-development-101');
        expect(tutorial, isNotNull);

        // 2️⃣ IDE: 코드 수정
        final modifiedCode = tutorial.code + '\n// 수정: 색상 추가';

        // 3️⃣ RUNNER: 실행 테스트
        var result = await FlEngineBridge.run(modifiedCode);
        expect(result.success, true);

        // 4️⃣ GAME: DSL 렌더링
        final gameContext = context.runGame(modifiedCode);
        expect(gameContext, isNotNull);

        // 5️⃣ HUB: 결과 공유
        context.shareSnippet(
          modifiedCode,
          tags: ['game', 'learned-from-tutorial'],
        );

        // 루프 검증
        expect(context.getUserJourney(), equals([
          'HUB_DISCOVER',
          'IDE_EDIT',
          'RUNNER_TEST',
          'GAME_RUN',
          'HUB_SHARE',
        ]));

        // 통계 업데이트 확인
        expect(context.getUserStats().contributionsCount, greaterThan(0));
      });

      test('신규 사용자 온보딩 완료 흐름', () async {
        context.createUser('new_user');

        // 단계별 진행
        // 1️⃣ Hello World (Runner)
        var result = await FlEngineBridge.run('print "Hello, FreeLang!"');
        expect(result.success, true);
        context.recordOnboardingStep('new_user', 'hello_world', 1);

        // 2️⃣ 변수 (IDE)
        result = await FlEngineBridge.run('let x = 42\nprint x');
        expect(result.success, true);
        context.recordOnboardingStep('new_user', 'variables', 2);

        // 3️⃣ 함수 (IDE)
        result = await FlEngineBridge.run('let double(n) { n * 2 }\nprint double(21)');
        expect(result.success, true);
        context.recordOnboardingStep('new_user', 'functions', 3);

        // 4️⃣ 게임 (Game)
        const simpleDsl = 'scene { sprite Player { x=160 } }';
        final gameCtx = context.runGame(simpleDsl);
        expect(gameCtx, isNotNull);
        context.recordOnboardingStep('new_user', 'game_dsl', 4);

        // 5️⃣ 공유 (Hub)
        context.shareSnippet(
          'let welcome = "I learned FreeLang!"\nprint welcome',
          author: 'new_user',
        );
        context.recordOnboardingStep('new_user', 'sharing', 5);

        // 온보딩 완료 확인
        final onboardingProgress = context.getUserOnboardingProgress('new_user');
        expect(onboardingProgress, equals(1.0)); // 100% 완료
      });
    });

    // ==================== 시나리오 6: 에러 복구 & 재시도 ====================
    group('시나리오 6: 에러 처리 & 복구', () {
      test('네트워크 오류 복구', () async {
        // Hub API 연결 실패 시뮬레이션
        context.simulateNetworkFailure();

        // 로컬 캐시에서 로드 시도
        final cachedSnippets = context.getLocalCachedSnippets();
        expect(cachedSnippets, isNotEmpty);

        // 네트워크 복구
        context.restoreNetworkConnection();

        // 재시도
        final snippets = context.fetchSnippetsWithRetry();
        expect(snippets, isNotEmpty);
      });

      test('코드 검증 오류 처리', () async {
        const invalidCode = 'let x = ) { invalid }';

        final errors = await FlEngineBridge.check(invalidCode);
        expect(errors, isNotEmpty);

        // IDE에서 오류 강조표시
        context.showErrorsInEditor(errors);
        expect(context.errorHighlightCount(), greaterThan(0));

        // 수정된 코드
        const fixedCode = 'let x = { value: 42 }';
        final fixedErrors = await FlEngineBridge.check(fixedCode);
        expect(fixedErrors, isEmpty);
      });
    });
  });
}

// ==================== 테스트 헬퍼 클래스 ====================
class ScenarioContext {
  final List<String> completedTutorials = [];
  final Map<String, dynamic> users = {};
  final Map<String, dynamic> snippets = {};
  String lastSnippetId = '';
  bool _networkFailure = false;
  final List<String> _userJourney = [];

  void createUser(String userId) {
    users[userId] = {
      'id': userId,
      'createdAt': DateTime.now(),
      'stats': {'contributions': 0, 'likes': 0},
    };
  }

  Map<String, dynamic> findTutorial(String tutorialId) {
    return {
      'id': tutorialId,
      'title': 'Tutorial: $tutorialId',
      'snippetId': 'tutorial_$tutorialId',
      'code': 'print "$tutorialId"',
    };
  }

  dynamic openIDEWithSnippet(String snippetId) {
    _userJourney.add('IDE_EDIT');
    return {'code': 'print "Hello"', 'snippetId': snippetId};
  }

  void recordLearning({
    required String tutorialId,
    required bool completed,
    int? timeMs,
  }) {
    if (completed) {
      completedTutorials.add(tutorialId);
    }
  }

  void saveSnippet(String id, String code) {
    snippets[id] = {'code': code, 'savedAt': DateTime.now()};
    lastSnippetId = id;
  }

  void shareSnippet(
    String code, {
    required String author,
    String title = 'Untitled',
    List<String> tags = const [],
  }) {
    _userJourney.add('HUB_SHARE');
    lastSnippetId = 'snippet_${DateTime.now().millisecondsSinceEpoch}';
    snippets[lastSnippetId] = {
      'code': code,
      'author': author,
      'title': title,
      'tags': tags,
      'likes': 0,
    };
  }

  double measureExecutionTime(String code) {
    // 시뮬레이션
    return (code.length / 1000.0);
  }

  int getSnippetLikes(String snippetId) {
    return snippets[snippetId]?['likes'] ?? 0;
  }

  int getCommunitySize() {
    return users.length;
  }

  void recordBugFix({
    required String originalCode,
    required String fixedCode,
  }) {
    _userJourney.add('BUG_FIX');
  }

  void likeSnippet(String snippetId) {
    if (snippets.containsKey(snippetId)) {
      snippets[snippetId]['likes'] = (snippets[snippetId]['likes'] ?? 0) + 1;
    }
  }

  String forkSnippet({
    required String originalSnippetId,
    required String newCode,
    required String author,
  }) {
    final forkId = 'fork_$originalSnippetId';
    snippets[forkId] = {
      'code': newCode,
      'author': author,
      'forkedFrom': originalSnippetId,
    };
    return forkId;
  }

  void createTutorial({
    required String title,
    required String code,
    required List<String> steps,
    required String author,
  }) {
    _userJourney.add('TUTORIAL_CREATE');
  }

  void recordTutorialCompletion(String userId, {required double progress}) {
    if (users.containsKey(userId)) {
      users[userId]['tutorialProgress'] = progress;
    }
  }

  double getTutorialCompletionRate() {
    if (users.isEmpty) return 0.0;
    final completed = users.values
        .where((u) => (u['tutorialProgress'] ?? 0) == 1.0)
        .length;
    return completed / users.length;
  }

  dynamic runGame(String dsl) {
    _userJourney.add('GAME_RUN');
    return GameContext(dsl);
  }

  List<String> getUserJourney() {
    return _userJourney;
  }

  Map<String, dynamic> getUserStats() {
    return {
      'contributionsCount': snippets.length,
      'likesCount': snippets.values
          .fold<int>(0, (sum, s) => sum + (s['likes'] ?? 0)),
    };
  }

  void recordOnboardingStep(String userId, String step, int number) {
    _userJourney.add('ONBOARDING_$number');
  }

  double getUserOnboardingProgress(String userId) {
    return _userJourney.where((j) => j.startsWith('ONBOARDING_')).length / 5;
  }

  void simulateNetworkFailure() {
    _networkFailure = true;
  }

  void restoreNetworkConnection() {
    _networkFailure = false;
  }

  List<dynamic> getLocalCachedSnippets() {
    return snippets.values.toList();
  }

  List<dynamic> fetchSnippetsWithRetry() {
    return snippets.values.toList();
  }

  void showErrorsInEditor(List<dynamic> errors) {
    // 시뮬레이션
  }

  int errorHighlightCount() {
    return 1; // 시뮬레이션
  }

  Future<void> cleanup() async {
    users.clear();
    snippets.clear();
    completedTutorials.clear();
    _userJourney.clear();
  }
}

