     1→// snippets.go - FreeLang 스니펫 REST API (중급)
     2→// 엔드포인트: /api/v2/snippets (CRUD + 검색 + 좋아요)
     3→
     4→package api
     5→
     6→import (
     7→	"database/sql"
     8→	"encoding/json"
     9→	"fmt"
    10→	"net/http"
    11→	"strconv"
    12→	"time"
    13→)
    14→
    15→// ==================== 데이터 모델 ====================
    16→
    17→type Snippet struct {
    18→	ID        string    `json:"id"`
    19→	Title     string    `json:"title"`
    20→	Code      string    `json:"code"`
    21→	Author    string    `json:"author"`
    22→	Tags      []string  `json:"tags"`
    23→	Likes     int       `json:"likes"`
    24→	CreatedAt time.Time `json:"created_at"`
    25→	UpdatedAt time.Time `json:"updated_at"`
    26→}
    27→
    28→type CreateSnippetRequest struct {
    29→	Title  string   `json:"title"`
    30→	Code   string   `json:"code"`
    31→	Author string   `json:"author"`
    32→	Tags   []string `json:"tags"`
    33→}
    34→
    35→type SnippetResponse struct {
    36→	Success bool        `json:"success"`
    37→	Data    interface{} `json:"data"`
    38→	Error   string      `json:"error,omitempty"`
    39→}
    40→
    41→type PaginatedResponse struct {
    42→	Success bool         `json:"success"`
    43→	Data    []Snippet    `json:"data"`
    44→	Total   int          `json:"total"`
    45→	Page    int          `json:"page"`
    46→	Limit   int          `json:"limit"`
    47→	Error   string       `json:"error,omitempty"`
    48→}
    49→
    50→// ==================== 데이터베이스 초기화 ====================
    51→
    52→func InitSnippetsTable(db *sql.DB) error {
    53→	schema := `
    54→	CREATE TABLE IF NOT EXISTS snippets (
    55→		id TEXT PRIMARY KEY,
    56→		title TEXT NOT NULL,
    57→		code TEXT NOT NULL,
    58→		author TEXT NOT NULL,
    59→		tags TEXT NOT NULL,
    60→		likes INTEGER DEFAULT 0,
    61→		created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    62→		updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
    63→	);
    64→
    65→	CREATE INDEX IF NOT EXISTS idx_snippets_author ON snippets(author);
    66→	CREATE INDEX IF NOT EXISTS idx_snippets_created_at ON snippets(created_at DESC);
    67→	`
    68→
    69→	_, err := db.Exec(schema)
    70→	return err
    71→}
    72→
    73→// ==================== 핸들러 ====================
    74→
    75→// GET /api/v2/snippets - 스니펫 목록 (페이징, 필터)
    76→func GetSnippets(db *sql.DB) http.HandlerFunc {
    77→	return func(w http.ResponseWriter, r *http.Request) {
    78→		page := 1
    79→		limit := 10
    80→		tag := ""
    81→
    82→		if p := r.URL.Query().Get("page"); p != "" {
    83→			if v, err := strconv.Atoi(p); err == nil && v > 0 {
    84→				page = v
    85→			}
    86→		}
    87→		if l := r.URL.Query().Get("limit"); l != "" {
    88→			if v, err := strconv.Atoi(l); err == nil && v > 0 && v <= 100 {
    89→				limit = v
    90→			}
    91→		}
    92→		if t := r.URL.Query().Get("tag"); t != "" {
    93→			tag = t
    94→		}
    95→
    96→		offset := (page - 1) * limit
    97→
    98→		// 쿼리 구성
    99→		query := "SELECT id, title, code, author, tags, likes, created_at, updated_at FROM snippets"
   100→		args := []interface{}{}
   101→
   102→		if tag != "" {
   103→			query += " WHERE tags LIKE ?"
   104→			args = append(args, "%"+tag+"%")
   105→		}
   106→
   107→		query += " ORDER BY created_at DESC LIMIT ? OFFSET ?"
   108→		args = append(args, limit, offset)
   109→
   110→		rows, err := db.Query(query, args...)
   111→		if err != nil {
   112→			http.Error(w, err.Error(), http.StatusInternalServerError)
   113→			return
   114→		}
   115→		defer rows.Close()
   116→
   117→		var snippets []Snippet
   118→		for rows.Next() {
   119→			var s Snippet
   120→			var tags string
   121→			if err := rows.Scan(&s.ID, &s.Title, &s.Code, &s.Author, &tags, &s.Likes, &s.CreatedAt, &s.UpdatedAt); err != nil {
   122→				continue
   123→			}
   124→			if err := json.Unmarshal([]byte(tags), &s.Tags); err != nil {
   125→				s.Tags = []string{}
   126→			}
   127→			snippets = append(snippets, s)
   128→		}
   129→
   130→		// 총 개수
   131→		countQuery := "SELECT COUNT(*) FROM snippets"
   132→		countArgs := []interface{}{}
   133→		if tag != "" {
   134→			countQuery += " WHERE tags LIKE ?"
   135→			countArgs = append(countArgs, "%"+tag+"%")
   136→		}
   137→
   138→		var total int
   139→		db.QueryRow(countQuery, countArgs...).Scan(&total)
   140→
   141→		w.Header().Set("Content-Type", "application/json")
   142→		json.NewEncoder(w).Encode(PaginatedResponse{
   143→			Success: true,
   144→			Data:    snippets,
   145→			Total:   total,
   146→			Page:    page,
   147→			Limit:   limit,
   148→		})
   149→	}
   150→}
   151→
   152→// GET /api/v2/snippets/:id - 스니펫 단건 조회
   153→func GetSnippet(db *sql.DB) http.HandlerFunc {
   154→	return func(w http.ResponseWriter, r *http.Request) {
   155→		id := r.PathValue("id")
   156→
   157→		var s Snippet
   158→		var tags string
   159→		err := db.QueryRow(
   160→			"SELECT id, title, code, author, tags, likes, created_at, updated_at FROM snippets WHERE id = ?",
   161→			id,
   162→		).Scan(&s.ID, &s.Title, &s.Code, &s.Author, &tags, &s.Likes, &s.CreatedAt, &s.UpdatedAt)
   163→
   164→		if err == sql.ErrNoRows {
   165→			http.Error(w, "스니펫을 찾을 수 없습니다", http.StatusNotFound)
   166→			return
   167→		}
   168→		if err != nil {
   169→			http.Error(w, err.Error(), http.StatusInternalServerError)
   170→			return
   171→		}
   172→
   173→		if err := json.Unmarshal([]byte(tags), &s.Tags); err != nil {
   174→			s.Tags = []string{}
   175→		}
   176→
   177→		w.Header().Set("Content-Type", "application/json")
   178→		json.NewEncoder(w).Encode(SnippetResponse{
   179→			Success: true,
   180→			Data:    s,
   181→		})
   182→	}
   183→}
   184→
   185→// POST /api/v2/snippets - 스니펫 생성
   186→func CreateSnippet(db *sql.DB) http.HandlerFunc {
   187→	return func(w http.ResponseWriter, r *http.Request) {
   188→		var req CreateSnippetRequest
   189→		if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
   190→			http.Error(w, "Invalid request", http.StatusBadRequest)
   191→			return
   192→		}
   193→
   194→		// 유효성 검증
   195→		if req.Title == "" || req.Code == "" || req.Author == "" {
   196→			http.Error(w, "title, code, author는 필수입니다", http.StatusBadRequest)
   197→			return
   198→		}
   199→
   200→		// 스니펫 ID 생성
   201→		id := "snippet_" + fmt.Sprintf("%d", time.Now().UnixMilli())
   202→		now := time.Now()
   203→
   204→		// 태그 직렬화
   205→		tagsJSON, _ := json.Marshal(req.Tags)
   206→
   207→		_, err := db.Exec(
   208→			"INSERT INTO snippets (id, title, code, author, tags, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?)",
   209→			id, req.Title, req.Code, req.Author, string(tagsJSON), now, now,
   210→		)
   211→		if err != nil {
   212→			http.Error(w, err.Error(), http.StatusInternalServerError)
   213→			return
   214→		}
   215→
   216→		w.Header().Set("Content-Type", "application/json")
   217→		w.WriteHeader(http.StatusCreated)
   218→		json.NewEncoder(w).Encode(SnippetResponse{
   219→			Success: true,
   220→			Data: map[string]interface{}{
   221→				"id":         id,
   222→				"created_at": now,
   223→			},
   224→		})
   225→	}
   226→}
   227→
   228→// DELETE /api/v2/snippets/:id - 스니펫 삭제
   229→func DeleteSnippet(db *sql.DB) http.HandlerFunc {
   230→	return func(w http.ResponseWriter, r *http.Request) {
   231→		id := r.PathValue("id")
   232→
   233→		result, err := db.Exec("DELETE FROM snippets WHERE id = ?", id)
   234→		if err != nil {
   235→			http.Error(w, err.Error(), http.StatusInternalServerError)
   236→			return
   237→		}
   238→
   239→		affected, _ := result.RowsAffected()
   240→		if affected == 0 {
   241→			http.Error(w, "스니펫을 찾을 수 없습니다", http.StatusNotFound)
   242→			return
   243→		}
   244→
   245→		w.Header().Set("Content-Type", "application/json")
   246→		json.NewEncoder(w).Encode(SnippetResponse{
   247→			Success: true,
   248→			Data: map[string]string{
   249→				"message": "삭제되었습니다",
   250→			},
   251→		})
   252→	}
   253→}
   254→
   255→// POST /api/v2/snippets/:id/like - 스니펫 좋아요
   256→func LikeSnippet(db *sql.DB) http.HandlerFunc {
   257→	return func(w http.ResponseWriter, r *http.Request) {
   258→		id := r.PathValue("id")
   259→
   260→		_, err := db.Exec("UPDATE snippets SET likes = likes + 1 WHERE id = ?", id)
   261→		if err != nil {
