   125→/// 경로 B: C 코드 생성 후 네이티브 컴파일 (Android 성능)
   126→///
   127→/// 주의: iOS에서는 JIT 정책 위반으로 불가능
   128→#[no_mangle]
   129→pub extern "C" fn fl_run_native(
   130→    source: *const c_char,
   131→    timeout_ms: u32,
   132→) -> FlResult {
   133→    let source_cstr = match unsafe { CStr::from_ptr(source) }.to_str() {
   134→        Ok(s) => s.to_string(),
   135→        Err(_) => {
   136→            return FlResult {
   137→                success: 0,
   138→                output: create_cstring(""),
   139→                error: create_cstring("Invalid UTF-8 in source code"),
   140→                time_ms: 0,
   141→                exit_code: 1,
   142→            }
   143→        }
   144→    };
   145→
   146→    // 2. 실제 구현: freelang-to-c + TCC 컴파일
   147→    // TODO: freelang-to-c로 C 코드 생성 후 TCC/gcc로 컴파일
   148→
   149→    // 임시 구현
   150→    let output = format!("Native executed: {} chars\n", source_cstr.len());
   151→
   152→    FlResult {
   153→        success: 1,
   154→        output: create_cstring(&output),
   155→        error: create_cstring(""),
   156→        time_ms: 25,
   157→        exit_code: 0,
   158→    }
   159→}
   160→
   161→/// 구문 강조용 토큰화
   162→#[no_mangle]
   163→pub extern "C" fn fl_tokenize(
   164→    source: *const c_char,
   165→    out_count: *mut c_int,
   166→) -> *mut FlToken {
   167→    let source_cstr = match unsafe { CStr::from_ptr(source) }.to_str() {
   168→        Ok(s) => s,
   169→        Err(_) => {
   170→            unsafe { *out_count = 0 };
   171→            return ptr::null_mut();
   172→        }
   173→    };
   174→
   175→    // TODO: fv-lang-wasm 파서 사용
   176→    // 임시 구현: "let", "print" 등 키워드 감지
   177→
   178→    let mut tokens = Vec::new();
   179→    if source_cstr.contains("let") {
   180→        tokens.push(FlToken {
   181→            token_type: 0, // keyword
   182→            start: 0,
   183→            length: 3,
   184→        });
   185→    }
   186→
   187→    let count = tokens.len() as c_int;
   188→    unsafe { *out_count = count };
   189→
   190→    if tokens.is_empty() {
   191→        return ptr::null_mut();
   192→    }
   193→
   194→    let boxed = Box::leak(tokens.into_boxed_slice());
   195→    boxed.as_mut_ptr()
   196→}
   197→
   198→/// 실행 결과 메모리 해제
   199→#[no_mangle]
   200→pub extern "C" fn fl_result_free(result: *mut FlResult) {
   201→    if result.is_null() {
   202→        return;
   203→    }
   204→
   205→    unsafe {
   206→        let r = &*result;
   207→        if !r.output.is_null() {
   208→            let _ = CString::from_raw(r.output);
   209→        }
   210→        if !r.error.is_null() {
   211→            let _ = CString::from_raw(r.error);
   212→        }
   213→        let _ = Box::from_raw(result);
   214→    }
   215→}
   216→
   217→/// 토큰 배열 메모리 해제
   218→#[no_mangle]
   219→pub extern "C" fn fl_tokens_free(tokens: *mut FlToken, count: c_int) {
   220→    if tokens.is_null() || count <= 0 {
   221→        return;
   222→    }
   223→
   224→    unsafe {
   225→        let _ = Vec::from_raw_parts(tokens, count as usize, count as usize);
   226→    }
   227→}
   228→
   229→// ============================================================================
   230→// 유틸리티 함수
   231→// ============================================================================
   232→
   233→/// Rust String → C CString 변환 헬퍼
   234→fn create_cstring(s: &str) -> *mut c_char {
   235→    match CString::new(s) {
   236→        Ok(cstr) => cstr.into_raw(),
   237→        Err(_) => unsafe { CString::from_raw(ptr::null_mut()) }.into_raw(),
   238→    }
   239→}
