   372→// ==================== 인터셉터 ====================
   373→
   374→class LoggingInterceptor extends Interceptor {
   375→  @override
   376→  void onRequest(RequestOptions options, RequestInterceptorHandler handler) {
   377→    print('[API] ${options.method} ${options.path}');
   378→    handler.next(options);
   379→  }
   380→
   381→  @override
   382→  void onResponse(Response response, ResponseInterceptorHandler handler) {
   383→    print('[API] ✓ ${response.statusCode} ${response.requestOptions.path}');
   384→    handler.next(response);
   385→  }
   386→
   387→  @override
   388→  void onError(DioException err, ErrorInterceptorHandler handler) {
   389→    print('[API] ✗ ${err.response?.statusCode} - ${err.message}');
   390→    handler.next(err);
   391→  }
   392→}
   393→
   394→class ErrorInterceptor extends Interceptor {
   395→  @override
   396→  void onError(DioException err, ErrorInterceptorHandler handler) {
   397→    if (err.response?.statusCode == 401) {
   398→      // 미인증 - 로그인 재필요
   399→      print('[API] 인증 만료');
   400→    } else if (err.response?.statusCode == 429) {
   401→      // Rate limit
   402→      print('[API] 요청 제한 초과');
   403→    } else if (err.type == DioExceptionType.connectionTimeout ||
   404→        err.type == DioExceptionType.receiveTimeout) {
   405→      print('[API] 타임아웃');
   406→    }
   407→    handler.next(err);
   408→  }
   409→}
