// auth.go - JWT 인증 시스템
// Register, Login, GetMe, AuthMiddleware 구현

package api

import (
	"context"
	"crypto/rand"
	"database/sql"
	"encoding/json"
	"fmt"
	"net/http"
	"strings"
	"time"

	"github.com/golang-jwt/jwt/v5"
	"golang.org/x/crypto/bcrypt"
)

// ==================== 데이터 모델 ====================

type User struct {
	ID        string    `json:"id"`
	Username  string    `json:"username"`
	Email     string    `json:"email"`
	CreatedAt time.Time `json:"created_at"`
}

type Claims struct {
	UserID   string `json:"user_id"`
	Username string `json:"username"`
	jwt.RegisteredClaims
}

type RegisterRequest struct {
	Username string `json:"username"`
	Email    string `json:"email"`
	Password string `json:"password"`
}

type LoginRequest struct {
	Email    string `json:"email"`
	Password string `json:"password"`
}

// ==================== 테이블 초기화 ====================

func InitUsersTable(db *sql.DB) error {
	schema := `
	CREATE TABLE IF NOT EXISTS users (
		id TEXT PRIMARY KEY,
		username TEXT NOT NULL UNIQUE,
		email TEXT NOT NULL UNIQUE,
		password_hash TEXT NOT NULL,
		created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
	);

	CREATE UNIQUE INDEX IF NOT EXISTS idx_users_email ON users(email);
	CREATE UNIQUE INDEX IF NOT EXISTS idx_users_username ON users(username);
	`

	_, err := db.Exec(schema)
	return err
}

// ==================== 헬퍼 함수 ====================

func generateID(prefix string) string {
	b := make([]byte, 8)
	rand.Read(b)
	return fmt.Sprintf("%s_%d", prefix, time.Now().UnixMilli())
}

// ==================== HTTP 핸들러 ====================

// POST /api/v2/auth/register
func Register(db *sql.DB, jwtSecret string) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		var req RegisterRequest
		if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
			WriteError(w, http.StatusBadRequest, "Invalid request body")
			return
		}

		// 검증
		if req.Username == "" || req.Email == "" || req.Password == "" {
			WriteError(w, http.StatusBadRequest, "Username, email, password required")
			return
		}

		if len(req.Password) < 6 {
			WriteError(w, http.StatusBadRequest, "Password must be at least 6 characters")
			return
		}

		// 중복 확인
		var existingID string
		err := db.QueryRow("SELECT id FROM users WHERE email = ?", req.Email).Scan(&existingID)
		if err != sql.ErrNoRows {
			WriteError(w, http.StatusConflict, "Email already registered")
			return
		}

		err = db.QueryRow("SELECT id FROM users WHERE username = ?", req.Username).Scan(&existingID)
		if err != sql.ErrNoRows {
			WriteError(w, http.StatusConflict, "Username already taken")
			return
		}

		// 비밀번호 해싱
		hash, err := bcrypt.GenerateFromPassword([]byte(req.Password), bcrypt.DefaultCost)
		if err != nil {
			WriteError(w, http.StatusInternalServerError, "Password hashing failed")
			return
		}

		// 사용자 생성
		userID := generateID("user")
		now := time.Now().UTC()
		_, err = db.Exec(
			"INSERT INTO users (id, username, email, password_hash, created_at) VALUES (?, ?, ?, ?, ?)",
			userID, req.Username, req.Email, string(hash), now,
		)
		if err != nil {
			WriteError(w, http.StatusInternalServerError, "Failed to create user")
			return
		}

		user := User{
			ID:        userID,
			Username:  req.Username,
			Email:     req.Email,
			CreatedAt: now,
		}

		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(map[string]interface{}{
			"success": true,
			"data":    user,
		})
	}
}

// POST /api/v2/auth/login
func Login(db *sql.DB, jwtSecret string) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		var req LoginRequest
		if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
			WriteError(w, http.StatusBadRequest, "Invalid request body")
			return
		}

		// 사용자 조회
		var userID string
		var username string
		var passwordHash string
		err := db.QueryRow(
			"SELECT id, username, password_hash FROM users WHERE email = ?",
			req.Email,
		).Scan(&userID, &username, &passwordHash)

		if err == sql.ErrNoRows {
			WriteError(w, http.StatusUnauthorized, "Invalid email or password")
			return
		}
		if err != nil {
			WriteError(w, http.StatusInternalServerError, "Database error")
			return
		}

		// 비밀번호 검증
		if err := bcrypt.CompareHashAndPassword([]byte(passwordHash), []byte(req.Password)); err != nil {
			WriteError(w, http.StatusUnauthorized, "Invalid email or password")
			return
		}

		// JWT 생성 (7일 만료)
		claims := Claims{
			UserID:   userID,
			Username: username,
			RegisteredClaims: jwt.RegisteredClaims{
				ExpiresAt: jwt.NewNumericDate(time.Now().Add(7 * 24 * time.Hour)),
				IssuedAt:  jwt.NewNumericDate(time.Now()),
			},
		}

		token := jwt.NewWithClaims(jwt.SigningMethodHS256, claims)
		tokenString, err := token.SignedString([]byte(jwtSecret))
		if err != nil {
			WriteError(w, http.StatusInternalServerError, "Token generation failed")
			return
		}

		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(map[string]interface{}{
			"success": true,
			"data": map[string]interface{}{
				"token": tokenString,
				"user": map[string]interface{}{
					"id":       userID,
					"username": username,
					"email":    req.Email,
				},
			},
		})
	}
}

// GET /api/v2/auth/me
func GetMe(db *sql.DB, jwtSecret string) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		// Context에서 user_id 추출 (AuthMiddleware가 설정)
		userID, ok := r.Context().Value("user_id").(string)
		if !ok {
			WriteError(w, http.StatusUnauthorized, "User not authenticated")
			return
		}

		var user User
		err := db.QueryRow(
			"SELECT id, username, email, created_at FROM users WHERE id = ?",
			userID,
		).Scan(&user.ID, &user.Username, &user.Email, &user.CreatedAt)

		if err == sql.ErrNoRows {
			WriteError(w, http.StatusNotFound, "User not found")
			return
		}
		if err != nil {
			WriteError(w, http.StatusInternalServerError, "Database error")
			return
		}

		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(map[string]interface{}{
			"success": true,
			"data":    user,
		})
	}
}

// ==================== 미들웨어 ====================

// AuthMiddleware - JWT 검증
func AuthMiddleware(jwtSecret string) func(http.HandlerFunc) http.HandlerFunc {
	return func(next http.HandlerFunc) http.HandlerFunc {
		return func(w http.ResponseWriter, r *http.Request) {
