// profile_screen.dart - 사용자 프로필 (동적 데이터)

import 'package:flutter/material.dart';
import 'package:hub/main.dart';
import 'package:hub/screens/login_screen.dart';
import 'package:hub/services/auth_service.dart';
import 'package:hub/services/hub_api_client.dart';

class ProfileScreen extends StatefulWidget {
  const ProfileScreen({Key? key}) : super(key: key);

  @override
  State<ProfileScreen> createState() => _ProfileScreenState();
}

class _ProfileScreenState extends State<ProfileScreen> {
  final _authService = AuthService();
  final _apiClient = HubApiClient();

  UserProfile? _profile;
  List<SnippetResponse> _mySnippets = [];
  bool _isLoading = true;
  String? _error;

  @override
  void initState() {
    super.initState();
    _loadProfile();
  }

  // ==================== 데이터 로드 ====================

  Future<void> _loadProfile() async {
    try {
      setState(() => _isLoading = true);

      // 현재 사용자 조회
      final profile = await _authService.getCurrentUser();
      if (profile == null) {
        setState(() {
          _error = '사용자 정보를 불러올 수 없습니다.';
          _isLoading = false;
        });
        return;
      }

      // 내 스니펫 조회
      final snippets = await _apiClient.getUserSnippets(author: profile.username);

      setState(() {
        _profile = profile;
        _mySnippets = snippets;
        _isLoading = false;
        _error = null;
      });
    } catch (e) {
      setState(() {
        _error = '오류 발생: $e';
        _isLoading = false;
      });
    }
  }

  // ==================== 로그아웃 ====================

  Future<void> _handleLogout() async {
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('로그아웃'),
        content: const Text('정말 로그아웃하시겠습니까?'),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(ctx, false),
            child: const Text('취소'),
          ),
          TextButton(
            onPressed: () => Navigator.pop(ctx, true),
            child: const Text('로그아웃', style: TextStyle(color: Colors.red)),
          ),
        ],
      ),
    );

    if (confirmed == true) {
      await _authService.logout();
      if (!mounted) return;
      Navigator.of(context).pushReplacement(
        MaterialPageRoute(builder: (_) => const LoginScreen()),
      );
    }
  }

  // ==================== 뱃지 로직 ====================

  List<BadgeInfo> _calculateBadges() {
    if (_profile == null || _mySnippets.isEmpty) return [];

    final badges = <BadgeInfo>[];
    final snippetCount = _mySnippets.length;
    final totalLikes = _mySnippets.fold<int>(0, (sum, s) => sum + s.likes);

    // 🌟 Contributor: 5개 이상 공유
    if (snippetCount >= 5) {
      badges.add(BadgeInfo('⭐', 'Contributor', 'n스니펫 $snippetCount개 공유'));
    }

    // 🔥 Popular: 50개 이상 좋아요
    if (totalLikes >= 50) {
      badges.add(BadgeInfo('🔥', 'Popular', '좋아요 $totalLikes개 획득'));
    }

    // 🎯 Power User: 가입 후 30일 이상
    if (_profile != null) {
      try {
        final createdAt = DateTime.parse(_profile!.createdAt);
        final daysSinceCreated = DateTime.now().difference(createdAt).inDays;
        if (daysSinceCreated >= 7) {
          badges.add(BadgeInfo('👑', 'Power User', '${daysSinceCreated}일 활동 중'));
        }
      } catch (e) {
        // 날짜 파싱 실패 무시
      }
    }

    // 최대 3개만 표시
    return badges.take(3).toList();
  }

  // ==================== UI 빌드 ====================

  @override
  Widget build(BuildContext context) {
    if (_isLoading) {
      return Center(
        child: CircularProgressIndicator(color: Colors.teal[300]),
      );
    }

    if (_error != null || _profile == null) {
      return Center(
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            Text(_error ?? '프로필을 불러올 수 없습니다.'),
            const SizedBox(height: 16),
            ElevatedButton(
              onPressed: _loadProfile,
              child: const Text('다시 시도'),
            ),
          ],
        ),
      );
    }

    final badges = _calculateBadges();
    final totalLikes = _mySnippets.fold<int>(0, (sum, s) => sum + s.likes);
    final userInitial = _profile!.username.isNotEmpty
        ? _profile!.username[0].toUpperCase()
        : 'U';

    // 가입일 포맷팅
    String formattedDate = '';
    try {
      final createdAt = DateTime.parse(_profile!.createdAt);
      formattedDate =
          '${createdAt.year}년 ${createdAt.month}월 ${createdAt.day}일';
    } catch (e) {
      formattedDate = _profile!.createdAt;
    }

    return SingleChildScrollView(
      child: Column(
        children: [
          // ==================== 프로필 헤더 ====================
          Container(
            color: Colors.teal[100],
            padding: const EdgeInsets.all(24),
            child: Column(
              children: [
                CircleAvatar(
                  radius: 50,
                  backgroundColor: Colors.teal[300],
                  child: Text(
                    userInitial,
                    style: const TextStyle(
                      fontSize: 32,
                      fontWeight: FontWeight.bold,
                      color: Colors.white,
                    ),
                  ),
                ),
                const SizedBox(height: 16),
                Text(
                  _profile!.username,
                  style: const TextStyle(
                    fontSize: 20,
                    fontWeight: FontWeight.bold,
                  ),
                ),
                const SizedBox(height: 4),
                Text(
                  _profile!.email,
                  style: TextStyle(
                    fontSize: 14,
                    color: Colors.grey[700],
                  ),
                ),
                const SizedBox(height: 8),
                Text(
                  '가입일: $formattedDate',
                  style: TextStyle(
                    fontSize: 12,
                    color: Colors.grey[700],
                  ),
                ),
              ],
            ),
          ),

          // ==================== 통계 ====================
          Padding(
            padding: const EdgeInsets.all(16),
            child: Row(
              mainAxisAlignment: MainAxisAlignment.spaceAround,
              children: [
                _buildStatCard('기여도', '${_mySnippets.length}', '스니펫'),
                _buildStatCard('좋아요', '$totalLikes', '개'),
                _buildStatCard('순위', 'N/A', '위'),
              ],
            ),
          ),

          // ==================== 뱃지 ====================
          if (badges.isNotEmpty)
            Padding(
              padding: const EdgeInsets.symmetric(horizontal: 16),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  const Text(
                    '뱃지',
                    style: TextStyle(
                      fontSize: 16,
                      fontWeight: FontWeight.bold,
                    ),
                  ),
                  const SizedBox(height: 12),
                  Wrap(
                    spacing: 12,
                    runSpacing: 12,
                    children: badges
                        .map((badge) => _buildBadge(
                            badge.emoji, badge.title, badge.description))
                        .toList(),
                  ),
                ],
              ),
            ),

          const SizedBox(height: 24),

          // ==================== 내 스니펫 ====================
          Padding(
            padding: const EdgeInsets.symmetric(horizontal: 16),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                const Text(
                  '내 스니펫',
                  style: TextStyle(
                    fontSize: 16,
                    fontWeight: FontWeight.bold,
                  ),
                ),
                const SizedBox(height: 12),
                if (_mySnippets.isEmpty)
                  Padding(
                    padding: const EdgeInsets.symmetric(vertical: 24),
                    child: Center(
                      child: Text(
                        '아직 공유한 스니펫이 없습니다.',
                        style: TextStyle(color: Colors.grey[600]),
                      ),
                    ),
                  )
                else
                  ..._mySnippets
                      .map((snippet) => _buildSnippetItem(
                            snippet.title,
                            _formatDate(snippet.createdAt),
                            snippet.likes,
                          ))
                      .toList(),
              ],
            ),
          ),

          const SizedBox(height: 24),

          // ==================== 설정 & 로그아웃 ====================
          Padding(
            padding: const EdgeInsets.symmetric(horizontal: 16),
            child: Column(
              children: [
                ListTile(
                  leading: const Icon(Icons.settings),
                  title: const Text('설정'),
                  trailing: const Icon(Icons.arrow_forward_ios, size: 16),
                  onTap: () {
                    ScaffoldMessenger.of(context).showSnackBar(
                      const SnackBar(content: Text('준비 중입니다.')),
                    );
                  },
                ),
                ListTile(
                  leading: const Icon(Icons.refresh),
                  title: const Text('새로고침'),
                  trailing: const Icon(Icons.arrow_forward_ios, size: 16),
                  onTap: _loadProfile,
                ),
                ListTile(
                  leading: const Icon(Icons.logout, color: Colors.red),
                  title: const Text(
                    '로그아웃',
                    style: TextStyle(color: Colors.red),
                  ),
                  onTap: _handleLogout,
                ),
              ],
            ),
          ),

          const SizedBox(height: 24),
        ],
      ),
    );
  }

  // ==================== 헬퍼 함수 ====================

  Widget _buildStatCard(String label, String value, String unit) {
    return Column(
      children: [
        Text(
          value,
          style: TextStyle(
            fontSize: 20,
            fontWeight: FontWeight.bold,
            color: Colors.teal[600],
          ),
        ),
        Text(
          unit,
          style: const TextStyle(fontSize: 12, color: Colors.grey),
        ),
        const SizedBox(height: 4),
        Text(
          label,
          style: const TextStyle(fontSize: 12, fontWeight: FontWeight.bold),
        ),
      ],
    );
  }

  Widget _buildBadge(String emoji, String title, String description) {
    return Column(
      children: [
        Container(
          width: 60,
          height: 60,
          decoration: BoxDecoration(
            color: Colors.teal[100],
            borderRadius: BorderRadius.circular(8),
          ),
          child: Center(
            child: Text(emoji, style: const TextStyle(fontSize: 24)),
          ),
        ),
        const SizedBox(height: 4),
        Text(
          title,
          style: const TextStyle(fontSize: 11, fontWeight: FontWeight.bold),
          textAlign: TextAlign.center,
        ),
        Text(
          description,
          style: const TextStyle(fontSize: 9, color: Colors.grey),
          textAlign: TextAlign.center,
          maxLines: 1,
          overflow: TextOverflow.ellipsis,
        ),
      ],
    );
  }

  Widget _buildSnippetItem(String title, String date, int likes) {
    return Card(
      margin: const EdgeInsets.only(bottom: 8),
      child: ListTile(
        title: Text(title),
        subtitle: Text(date),
        trailing: Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            Icon(Icons.favorite, color: Colors.red, size: 16),
            const SizedBox(width: 4),
            Text('$likes'),
          ],
        ),
      ),
    );
  }

  String _formatDate(String dateString) {
    try {
      final date = DateTime.parse(dateString);
      final now = DateTime.now();
      final diff = now.difference(date);

      if (diff.inDays == 0) {
        if (diff.inHours == 0) {
          return '${diff.inMinutes}분 전';
        }
        return '${diff.inHours}시간 전';
      } else if (diff.inDays < 7) {
        return '${diff.inDays}일 전';
      } else if (diff.inDays < 30) {
        return '${(diff.inDays / 7).floor()}주 전';
      } else {
        return '${(diff.inDays / 30).floor()}개월 전';
      }
    } catch (e) {
      return dateString;
    }
  }
}

// ==================== 모델 ====================

class BadgeInfo {
  final String emoji;
  final String title;
  final String description;

  BadgeInfo(this.emoji, this.title, this.description);
}

