// comment_screen.dart - 스니펫 댓글 화면

import 'package:flutter/material.dart';
import 'package:hub/screens/login_screen.dart';
import 'package:hub/services/auth_service.dart';
import 'package:hub/services/hub_api_client.dart';

class CommentScreen extends StatefulWidget {
  final SnippetResponse snippet;

  const CommentScreen({Key? key, required this.snippet}) : super(key: key);

  @override
  State<CommentScreen> createState() => _CommentScreenState();
}

class _CommentScreenState extends State<CommentScreen> {
  final _authService = AuthService();
  final _apiClient = HubApiClient();
  final _contentController = TextEditingController();

  List<CommentResponse> _comments = [];
  bool _isLoading = true;
  bool _isSubmitting = false;
  bool _isLoggedIn = false;

  @override
  void initState() {
    super.initState();
    _loadData();
  }

  @override
  void dispose() {
    _contentController.dispose();
    super.dispose();
  }

  // ==================== 데이터 로드 ====================

  Future<void> _loadData() async {
    try {
      // 로그인 상태 확인
      final loggedIn = await _authService.isLoggedIn();
      setState(() => _isLoggedIn = loggedIn);

      // 댓글 목록 로드
      final comments = await _apiClient.getComments(widget.snippet.id);
      setState(() {
        _comments = comments;
        _isLoading = false;
      });
    } catch (e) {
      print('Error loading comments: $e');
      setState(() => _isLoading = false);
    }
  }

  // ==================== 댓글 제출 ====================

  Future<void> _submitComment() async {
    final content = _contentController.text.trim();

    if (content.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('댓글을 입력해주세요.')),
      );
      return;
    }

    // 로그인 확인
    if (!_isLoggedIn) {
      final result = await Navigator.push<bool>(
        context,
        MaterialPageRoute(builder: (_) => const LoginScreen()),
      );

      if (result == true) {
        setState(() => _isLoggedIn = true);
        // 로그인 후 다시 제출
        _submitComment();
      }
      return;
    }

    setState(() => _isSubmitting = true);

    try {
      await _apiClient.createComment(widget.snippet.id, content);

      // 댓글 목록 새로고침
      await _loadData();

      _contentController.clear();

      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('댓글이 등록되었습니다.')),
        );
      }
    } catch (e) {
      print('Error creating comment: $e');
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text('댓글 등록 실패: $e')),
        );
      }
    } finally {
      if (mounted) {
        setState(() => _isSubmitting = false);
      }
    }
  }

  // ==================== UI 빌드 ====================

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: Text(widget.snippet.title),
        elevation: 0,
        backgroundColor: Colors.grey[900],
      ),
      body: Column(
        children: [
          // ==================== 스니펫 미리보기 ====================
          Container(
            color: Colors.grey[900],
            padding: const EdgeInsets.all(16),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  '코드:',
                  style: TextStyle(
                    fontSize: 12,
                    color: Colors.grey[500],
                    fontWeight: FontWeight.bold,
                  ),
                ),
                const SizedBox(height: 8),
                Container(
                  width: double.infinity,
                  padding: const EdgeInsets.all(12),
                  decoration: BoxDecoration(
                    color: Colors.grey[850],
                    borderRadius: BorderRadius.circular(8),
                  ),
                  child: Text(
                    widget.snippet.code.length > 200
                        ? '${widget.snippet.code.substring(0, 200)}...'
                        : widget.snippet.code,
                    style: const TextStyle(
                      fontFamily: 'Courier',
                      fontSize: 12,
                      color: Colors.grey,
                    ),
                    maxLines: 5,
                    overflow: TextOverflow.ellipsis,
                  ),
                ),
                const SizedBox(height: 8),
                Row(
                  children: [
                    Icon(Icons.favorite, color: Colors.red, size: 16),
                    const SizedBox(width: 4),
                    Text(
                      '${widget.snippet.likes}',
                      style: const TextStyle(fontSize: 12),
                    ),
                    const SizedBox(width: 16),
                    Icon(Icons.person, color: Colors.blue, size: 16),
                    const SizedBox(width: 4),
                    Text(
                      widget.snippet.author,
                      style: const TextStyle(fontSize: 12),
                    ),
                  ],
                ),
              ],
            ),
          ),

          // ==================== 댓글 구분선 ====================
          Container(
            height: 1,
            color: Colors.grey[800],
          ),

          // ==================== 댓글 목록 ====================
          Expanded(
            child: _isLoading
                ? Center(
                    child: CircularProgressIndicator(
                      color: Colors.teal[300],
                    ),
                  )
                : _comments.isEmpty
                    ? Center(
                        child: Text(
                          '아직 댓글이 없습니다.\n첫 댓글을 남겨보세요!',
                          textAlign: TextAlign.center,
                          style: TextStyle(color: Colors.grey[600]),
                        ),
                      )
                    : ListView.separated(
                        itemCount: _comments.length,
                        separatorBuilder: (_, __) => Divider(
                          color: Colors.grey[800],
                          height: 1,
                        ),
                        itemBuilder: (context, index) {
                          final comment = _comments[index];
                          return _buildCommentItem(comment);
                        },
                      ),
          ),

          // ==================== 댓글 입력 ====================
          Container(
            color: Colors.grey[900],
            padding: const EdgeInsets.all(12),
            child: Row(
              children: [
                Expanded(
                  child: TextField(
                    controller: _contentController,
                    style: const TextStyle(color: Colors.white),
                    maxLines: null,
                    maxLength: 200,
                    decoration: InputDecoration(
                      hintText: _isLoggedIn ? '댓글을 입력하세요...' : '로그인 후 댓글 작성',
                      hintStyle: TextStyle(color: Colors.grey[600]),
                      filled: true,
                      fillColor: Colors.grey[850],
                      border: OutlineInputBorder(
                        borderRadius: BorderRadius.circular(8),
                        borderSide: BorderSide.none,
                      ),
                      contentPadding: const EdgeInsets.symmetric(
                        horizontal: 12,
                        vertical: 10,
                      ),
                      counter: const SizedBox.shrink(),
                    ),
                    enabled: _isLoggedIn && !_isSubmitting,
                  ),
                ),
                const SizedBox(width: 8),
                SizedBox(
                  width: 48,
                  height: 48,
                  child: ElevatedButton(
                    onPressed: _isLoggedIn && !_isSubmitting ? _submitComment : null,
                    style: ElevatedButton.styleFrom(
                      backgroundColor: Colors.teal[600],
                      disabledBackgroundColor: Colors.grey[700],
                      padding: EdgeInsets.zero,
                      shape: RoundedRectangleBorder(
                        borderRadius: BorderRadius.circular(8),
                      ),
                    ),
                    child: _isSubmitting
                        ? const SizedBox(
                            width: 20,
                            height: 20,
                            child: CircularProgressIndicator(
                              strokeWidth: 2,
                              valueColor:
                                  AlwaysStoppedAnimation<Color>(Colors.white),
                            ),
                          )
                        : const Icon(Icons.send, size: 20),
                  ),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }

  // ==================== 댓글 아이템 ====================

  Widget _buildCommentItem(CommentResponse comment) {
    final userInitial = comment.username.isNotEmpty
        ? comment.username[0].toUpperCase()
        : 'U';

    String formattedTime = '';
    try {
      final createdAt = DateTime.parse(comment.createdAt);
      final now = DateTime.now();
      final diff = now.difference(createdAt);

      if (diff.inMinutes < 1) {
        formattedTime = '방금';
      } else if (diff.inHours < 1) {
        formattedTime = '${diff.inMinutes}분 전';
      } else if (diff.inDays < 1) {
        formattedTime = '${diff.inHours}시간 전';
      } else {
        formattedTime = '${diff.inDays}일 전';
      }
    } catch (e) {
      formattedTime = comment.createdAt;
    }

    return Padding(
      padding: const EdgeInsets.all(12),
      child: Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          // 아바타
          CircleAvatar(
            radius: 20,
            backgroundColor: Colors.teal[600],
            child: Text(
              userInitial,
              style: const TextStyle(
                fontWeight: FontWeight.bold,
                color: Colors.white,
              ),
            ),
          ),

          const SizedBox(width: 12),

          // 댓글 내용
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Row(
                  mainAxisAlignment: MainAxisAlignment.spaceBetween,
                  children: [
                    Text(
                      comment.username,
                      style: const TextStyle(
                        fontWeight: FontWeight.bold,
                        fontSize: 14,
                      ),
                    ),
                    Text(
                      formattedTime,
                      style: TextStyle(
                        fontSize: 12,
                        color: Colors.grey[600],
                      ),
                    ),
                  ],
                ),
                const SizedBox(height: 4),
                Text(
                  comment.content,
                  style: const TextStyle(
                    fontSize: 13,
                    color: Colors.grey,
                  ),
                  maxLines: null,
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }
}

